  const policies=POLICIES_TEMPLATE.replaceAll('"__BOUND_PORTAL_READER_OWNER__"',identifier(i.readerOwner));
  const grants=GRANTS_TEMPLATE.replaceAll('"__BOUND_PORTAL_READER_OWNER__"',identifier(i.readerOwner));
  if(policies.includes('"__BOUND_PORTAL_READER_OWNER__"')||grants.includes('"__BOUND_PORTAL_READER_OWNER__"'))return deny();
  Object.assign(sourceBundle,{privatePoliciesTemplateSource:[...Buffer.from(POLICIES_TEMPLATE)],privateGrantsTemplateSource:[...Buffer.from(GRANTS_TEMPLATE)],privatePoliciesRenderedSource:[...Buffer.from(policies)],privateGrantsRenderedSource:[...Buffer.from(grants)],privateEnrollmentCaptureSource:[...captureBytes]});
