  if(one(await installer.query(HELD_SOURCE_CONTROLS_GRANT_RECONCILIATION_SQL,[heldSourceControls,currentHeldSourceControls,i.readerOwnerOid,i.installerRoleOid,i.readerOwner,i.installerRole,rootOid,body(ROOT_SOURCE,'protected_portal_source_resolver')]),['source_controls_match']).source_controls_match!==true)return deny();
