  if(native.format!=='PORTAL_STARTUP_NATIVE_GRAPH_OBSERVATION_V1'||native.databaseOid!==i.databaseOid||native.rootOid!==rootOid||native.ownerOid!==i.readerOwnerOid)return deny();
